  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "Ribociclib, a close analogue sharing the cyclopentyl and free piperazine-anilinopyrimidine motif, has 37–55% oral bioavailability in rats, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ribociclib has 64–87% oral bioavailability in dogs, further strengthening the transfer of high oral bioavailability to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A piperazine-anilinopyrimidine fused heterocycle with a cyclopentyl-like core has approximately 20–25% oral bioavailability in patients, meeting the F ≥ 20% threshold and supporting a high prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Brepocitinib, a heteroaromatic kinase inhibitor with a similar aminopyrimidine/piperazine-like motif, has approximately 75% absolute oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "The highest-Morgan analogue (lead compound 1) has only 9.4% absolute oral bioavailability in rats, below the threshold; however, its core lacks the acetyl/methyl/pyridone substituents and is a different extended aromatic system, limiting transferability to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Prediction: high. The query is a desmethyl-palbociclib-like pyrido[2,3-d]pyrimidinone with a free piperazine, closely related to ribociclib, which has 37–55% rat and 64–87% dog oral bioavailability, and to palbociclib, a clinically used oral drug. The only high-similarity low-F analogue (lead compound 1, 9.4% rat) lacks the polar acetyl/methyl/pyridone features and has a different extended aromatic core, limiting transferability. Multiple additional analogues with the piperazine-anilinopyrimidine motif show F ≥ 20% in humans. Therefore, F ≥ 20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability record for the query molecule.",
    "Ribociclib human absolute bioavailability is only qualitative ('orally bioavailable'); numeric values are from rat and dog.",
    "The closest low-F analogue (lead compound 1) is in rats and differs in core substitution, so its quantitative transferability is uncertain.",
    "No query-specific permeability, efflux, solubility, or food-effect data are available."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C15"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "lead_compound_1"
    },
    {
      "applicability": "high",
      "card_ids": ["C19", "C24", "C25", "C22", "C16", "C20", "C23"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "ribociclib"
    },
    {
      "applicability": "low",
      "card_ids": ["C14", "C21", "C18", "C17"],
      "decision_effect": "no_change",
      "direction": "supportive",
      "family": "other_kinase_inhibitors"
    }
  ],
  "revision_action": "keep"
}

